   1→#!/usr/bin/env bun
   2→/**
   3→ * onboard-centre.ts — Automated Code Ninjas Centre Onboarding
   4→ *
   5→ * Provisions a new centre across Twilio, Retell, Cekura, ChatDash, and Hiya
   6→ * in a single command. Executes 10 sequential steps with rollback-aware logging.
   7→ *
   8→ * Usage:
   9→ *   bun /root/lead-reactivation-github/scripts/onboard-centre.ts \
  10→ *     --name "Leaside" --area-code "647" --country CA \
  11→ *     --owner-name "Sharmila" --owner-email "sharmila@example.com"
  12→ *
  13→ * See onboard-centre.help.md for full documentation.
  14→ */
  15→
  16→import { parseArgs } from "util";
  17→
  18→// ─────────────────────────────────────────────────────────────
  19→// Configuration
  20→// ─────────────────────────────────────────────────────────────
  21→
