 237→async function twilioGet<T>(path: string): Promise<T> {
 238→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
 239→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
 240→  const res = await fetch(url, {
 241→    headers: { Authorization: `Basic ${auth}` },
 242→  });
 243→  if (!res.ok) {
 244→    const body = await res.text();
 245→    throw new Error(`Twilio GET ${path} → ${res.status}: ${body}`);
 246→  }
 247→  return res.json() as Promise<T>;
 248→}
 249→
 250→async function twilioPost<T>(path: string, formData: Record<string, string>): Promise<T> {
 251→  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
 252→  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
 253→  const body = new URLSearchParams(formData).toString();
 254→  const res = await fetch(url, {
 255→    method: "POST",
 256→    headers: {
 257→      Authorization: `Basic ${auth}`,
 258→      "Content-Type": "application/x-www-form-urlencoded",
 259→    },
 260→    body,
 261→  });
 262→  if (!res.ok) {
 263→    const text = await res.text();
 264→    throw new Error(`Twilio POST ${path} → ${res.status}: ${text}`);
 265→  }
 266→  return res.json() as Promise<T>;
 267→}
