 365→// ─────────────────────────────────────────────────────────────
 366→// Step 0: Discover Centre from codeninjas.com
 367→// ─────────────────────────────────────────────────────────────
 368→
 369→/**
 370→ * Lookup the centre slug from the codeninjas.com sitemap.
 371→ * Handles both US format ({state}-{name}) and CA format ({name}-{province}-{country}).
 372→ * Returns the slug (e.g., "burlington-on-ca") or null if not found.
 373→ */
 374→async function lookupCentreSlug(name: string): Promise<string | null> {
 375→  const sitemapRes = await fetch(CN_SITEMAP_URL, {
 376→    headers: { "User-Agent": "Mozilla/5.0 (compatible; onboard-centre/1.0)" },
 377→  });
 378→  if (!sitemapRes.ok) return null;
 379→  const sitemapXml = await sitemapRes.text();
 380→
 381→  // Sanitize name: "St. Catharines" → "st-catharines"
 382→  const nameSanitized = name.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
 383→
 384→  // Match any base URL slug containing the sanitized name
 385→  // This handles both US ({state}-{name}) and CA ({name}-{province}-{country}) formats
 386→  const urlPattern = new RegExp(
 387→    `https://www\\.codeninjas\\.com/([^/<"]*${nameSanitized}[^/<"]*)(?=[/<])`,
 388→    "gi"
 389→  );
 390→  const matches = [...new Set(
 391→    Array.from(sitemapXml.matchAll(urlPattern), (m) => m[0])
 392→  )];
 393→
 394→  if (matches.length === 0) return null;
 395→
 396→  // Deduplicate to base URLs (strip subpages like /jr, /camps, etc.)
 397→  const baseUrls = [...new Set(
 398→    matches.map((u) => {
 399→      const parts = new URL(u).pathname.split("/").filter(Boolean);
 400→      return `https://www.codeninjas.com/${parts[0]}`;
 401→    })
 402→  )];
 403→
 404→  if (baseUrls.length > 1) {
 405→    info(`Multiple locations found for "${name}":`);
 406→    for (const u of baseUrls) info(`  ${u}`);
 407→    return null; // Ambiguous — caller must resolve
 408→  }
 409→
 410→  return new URL(baseUrls[0]).pathname.slice(1); // e.g., "burlington-on-ca"
 411→}
 412→
 413→async function step0_discover(name: string): Promise<CentreDiscovery> {
 414→  stepHeader(0, "Discover Centre from codeninjas.com");
 415→
 416→  // Step 0a: Fetch sitemap and search for the centre slug
 417→  info(`Fetching sitemap from ${CN_SITEMAP_URL}...`);
 418→  const cnSlug = await lookupCentreSlug(name);
 419→  if (!cnSlug) {
 420→    throw new Error(
 421→      `Centre "${name}" not found in codeninjas.com sitemap. ` +
 422→      `Check spelling or provide --area-code manually.`
 423→    );
 424→  }
 425→  success(`Found centre: https://www.codeninjas.com/${cnSlug} (code: ${cnSlug})`);
 426→
 427→  // Step 0b: Fetch facility details from services API
 428→  info(`Fetching facility profile from services API...`);
 429→  const profileUrl = `${CN_SERVICES_BASE}/facility/profile/slug/${cnSlug}`;
 430→  const profileRes = await fetch(profileUrl);
 431→  if (!profileRes.ok) {
 432→    throw new Error(`Services API returned ${profileRes.status} for slug "${cnSlug}"`);
 433→  }
 434→  const profile = await profileRes.json() as Record<string, unknown>;
 435→
 436→  const phone = String(profile.phone ?? "");
 437→  const phoneDigits = phone.replace(/\D/g, "");
 438→  const discoveredAreaCode = phoneDigits.length >= 10 ? phoneDigits.slice(0, 3) : "";
 439→  const discoveredCountry = String(profile.countryCode ?? "US");
 440→
 441→  const discovery: CentreDiscovery = {
 442→    centreCode: cnSlug,
 443→    city: String(profile.city ?? ""),
 444→    state: String(profile.stateAbbreviation ?? ""),
 445→    stateName: String(profile.stateName ?? ""),
 446→    country: discoveredCountry,
 447→    postalCode: String(profile.postalCode ?? ""),
 448→    areaCode: discoveredAreaCode,
 449→    phone,
 450→    address: String(profile.streetAddress1 ?? ""),
 451→    email: String(profile.emailAddress ?? ""),
 452→    url: `https://www.codeninjas.com/${cnSlug}`,
 453→  };
 454→
 455→  success(`City: ${discovery.city}, ${discovery.state}`);
 456→  success(`Address: ${discovery.address}, ${discovery.postalCode}`);
 457→  success(`Phone: ${discovery.phone} (area code: ${discovery.areaCode})`);
 458→  success(`Country: ${discovery.country}`);
 459→  success(`Centre code: ${discovery.centreCode}`);
 460→
 461→  return discovery;
 462→}
