 464→// ─────────────────────────────────────────────────────────────
 465→// Step 1: Twilio — Sub-Account + Phone + SIP Trunk
 466→// ─────────────────────────────────────────────────────────────
 467→
 468→async function step1_twilioProvision(state: OnboardingState): Promise<void> {
 469→  stepHeader(1, "Twilio - Sub-Account + Phone + SIP Trunk");
 470→
 471→  const trunkDomain = `${slugName}-cnkb.pstn.twilio.com`;
 472→
 473→  if (dryRun) {
 474→    dryLog(`Would create sub-account "Code Ninjas ${centreName}"`);
 475→    dryLog(`Would search for ${country} numbers with area code ${areaCode}`);
 476→    dryLog(`Would purchase first available and name it "CNKB-${centreName}"`);
 477→    dryLog(`Would create SIP credential list + credential (${slugName})`);
 478→    dryLog(`Would create SIP trunk: ${trunkDomain}`);
 479→    dryLog(`Would add origination URI: sip:sip.retellai.com`);
 480→    dryLog(`Would associate credential list with trunk`);
 481→    dryLog(`Would link phone number to trunk`);
 482→    state.subAccountSid = "AC_dry_run_sub_sid";
 483→    state.subAccountToken = "dry_run_sub_token";
 484→    state.twilioNumber = `+${areaCode}5550100`;
 485→    state.twilioSid = "PN_dry_run_sid";
 486→    state.trunkDomain = trunkDomain;
 487→    state.trunkSid = "TK_dry_run_trunk_sid";
 488→    return;
 489→  }
 490→
 491→  // 1a. Create sub-account (top-level endpoint, not nested under parent account)
 492→  info(`Creating sub-account "Code Ninjas ${centreName}"...`);
 493→  const subAccountRes = await fetch(`${TWILIO_BASE}/Accounts.json`, {
 494→    method: "POST",
 495→    headers: {
 496→      Authorization: `Basic ${Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64")}`,
 497→      "Content-Type": "application/x-www-form-urlencoded",
 498→    },
 499→    body: new URLSearchParams({ FriendlyName: `Code Ninjas ${centreName}` }).toString(),
 500→  });
 501→  if (!subAccountRes.ok) {
 502→    const text = await subAccountRes.text();
 503→    throw new Error(`Twilio POST /Accounts.json → ${subAccountRes.status}: ${text}`);
 504→  }
 505→  const subAccount = await subAccountRes.json() as { sid: string; auth_token: string };
 506→  state.subAccountSid = subAccount.sid;
 507→  state.subAccountToken = subAccount.auth_token;
 508→  success(`Sub-account: ${subAccount.sid}`);
 509→
 510→  const subSid = subAccount.sid;
 511→  const subToken = subAccount.auth_token;
 512→
 513→  // 1b. Search and purchase phone number on sub-account
 514→  info(`Searching for ${country} numbers in area code ${areaCode}...`);
 515→  const searchPath = `/AvailablePhoneNumbers/${country}/Local.json?AreaCode=${areaCode}&Limit=5`;
 516→  const searchResult = await subTwilioGet<{ available_phone_numbers: TwilioNumber[] }>(subSid, subToken, searchPath);
 517→  const available = searchResult.available_phone_numbers;
 518→
 519→  if (!available || available.length === 0) {
 520→    throw new Error(`No available numbers found for area code ${areaCode} in ${country}`);
 521→  }
 522→
 523→  info(`Found ${available.length} available number(s):`);
