1111→async function step10_onboardingEmail(state: OnboardingState): Promise<void> {
1112→  stepHeader(10, "Client Onboarding Email");
1113→
1114→  let centreCode = state.discovery?.centreCode ?? "";
1115→  let director = ownerName;
1116→
1117→  // Look up director name and centre code from the sheet if not already known
1118→  if (!director || !centreCode) {
1119→    try {
1120→      info("Looking up director name from centre directory sheet...");
1121→      const csvUrl = `https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/gviz/tq?tqx=out:csv`;
1122→      const csvRes = await fetch(csvUrl);
1123→      if (csvRes.ok) {
1124→        const csv = await csvRes.text();
1125→        const rows = csv.split("\n");
1126→        for (const row of rows) {
1127→          // Parse CSV fields properly (handles quoted values)
1128→          const cols: string[] = [];
1129→          let current = "";
1130→          let inQuotes = false;
1131→          for (const ch of row) {
1132→            if (ch === '"') { inQuotes = !inQuotes; continue; }
1133→            if (ch === ',' && !inQuotes) { cols.push(current.trim()); current = ""; continue; }
1134→            current += ch;
1135→          }
1136→          cols.push(current.trim());
1137→
1138→          // Match on location_name (column 3) — case-insensitive
1139→          const locationName = cols[3] ?? "";
1140→          if (locationName.toLowerCase() === centreName.toLowerCase()) {
1141→            // Column 0 = centre_id, Column 8 = Director
1142→            if (!centreCode && cols[0]) {
1143→              centreCode = cols[0];
1144→              info(`Found centre code: ${centreCode}`);
1145→            }
1146→            const dirCol = cols[8] ?? "";
1147→            if (!director && dirCol) {
1148→              director = dirCol.split(" ")[0]; // First name only for salutation
1149→              info(`Found director: ${dirCol} (using "${director}" for salutation)`);
1150→            }
1151→            break;
1152→          }
1153→        }
1154→      }
1155→    } catch {
1156→      info("Could not look up from sheet — using available data");
1157→    }
1158→  }
1159→
1160→  // Final fallback for centre code
1161→  if (!centreCode) {
1162→    centreCode = centreName.toLowerCase().replace(/\s+/g, "-");
1163→  }
1164→
1165→  const fromNumber = (state.twilioNumber ?? "").replace("+", "");
1166→  const subject = `Code Ninjas ${centreName} — Getting Started`;
1167→  const html = buildOnboardingEmailHtml(director, centreCode, centreName, fromNumber);
1168→
1169→  if (dryRun) {
1170→    dryLog(`Would send onboarding email to ${ONBOARDING_EMAIL_TO}`);
1171→    dryLog(`Subject: ${subject}`);
1172→    dryLog(`Salutation: "Hi ${director || "there"}"`);
1173→    dryLog(`Centre code in email: ${centreCode}`);
1174→    dryLog(`Forwarding address: scott.james1717+${centreCode}@gmail.com`);
1175→    return;
1176→  }
1177→
1178→  info(`Sending onboarding email to ${ONBOARDING_EMAIL_TO}...`);
1179→
1180→  const res = await fetch("https://api.resend.com/emails", {
1181→    method: "POST",
1182→    headers: {
1183→      Authorization: `Bearer ${RESEND_API_KEY}`,
1184→      "Content-Type": "application/json",
1185→    },
1186→    body: JSON.stringify({
1187→      from: RESEND_FROM,
1188→      to: [ONBOARDING_EMAIL_TO],
1189→      subject,
1190→      html,
1191→    }),
1192→  });
1193→
1194→  if (!res.ok) {
1195→    throw new Error(`Resend API failed: ${res.status} ${await res.text()}`);
1196→  }
1197→
1198→  const result = await res.json() as { id: string };
1199→  ok(`Onboarding email sent (ID: ${result.id})`);
1200→  info(`Forward to the centre director when ready`);
1201→}
